#!/usr/bin/env bash
# ==============================================================================
# GNB Mentor Pay - Automated VPS Live Order & Google Pay Fix Updater
# Run directly in /var/www/pay.gnbmentor.com on your AlmaLinux VPS
# ==============================================================================
set -e

echo "=== [1/5] Checking directory ==="
cd /var/www/pay.gnbmentor.com

echo "=== [2/5] Extracting updated production code ==="
base64 -d << 'PAYLOAD_EOF' | tar -xz -C /var/www/pay.gnbmentor.com

PAYLOAD_EOF

echo "=== [3/5] Building production frontend assets ==="
npm run build

echo "=== [4/5] Restarting PM2 service ==="
pm2 restart gnbmentor-pay || pm2 start deploy/ecosystem.config.cjs --env production
pm2 save

echo "=== [5/5] Verifying API status ==="
sleep 2
curl -s http://127.0.0.1:3000/api/config
echo ""
echo "=========================================================="
echo " Update applied successfully! Live processing is active."
echo "=========================================================="
